function restore(state){punchTime=shieldBash=-10;fistMesh.visible=false;if(shield){camera.remove(shield);shield.traverse(n=>{if(n.isMesh){n.geometry.dispose();n.material.dispose()}});shield=null}mageShots=state.combat?.mageShots||0;rank=state.combat?.rank||0;skillReady=state.combat?.skillReady||0;rollReady=state.combat?.rollReady||0;rollAge=10;blocking.held=false;blocking.broken=false;chest.splice(0,18,...(state.chest||Array(18).fill(null)).map(i=>i?{...i}:null));lastHurtCue=-10;for(const key of Object.keys(createProgress()))p[key]=state.p[key]??createProgress()[key];lastKnownLevel=p.level;slots.splice(0,18,...state.slots.map(item=>item?{...item}:null));if(!state.combat&&p.classId==='sword'&&!slots.some(i=>i?.id==='shield')){if(!slots[1])slots[1]={id:'shield',count:1};else addItem(slots,'shield')}gear=gearBonus(slots);lastAttack=state.lastAttack;lastHurt=state.lastHurt;attackTime=state.attackTime;open=false;levelChoice=false;modal.hidden=true;keys.clear();if(weapon){camera.remove(weapon);weapon.traverse(n=>{if(n.isMesh){n.geometry.dispose();n.material.dispose()}});weapon=null}if(p.classId){buildWeapon();weapon.visible=weaponEquipped()}for(const b of bullets){scene.remove(b.m);b.m.geometry.dispose();b.m.material.dispose()}bullets.length=0;for(const b of state.bullets){const m=new T.Mesh(b.arrow?new T.CylinderGeometry(.012,.012,.55,5):new T.SphereGeometry(.09,8,6),new T.MeshBasicMaterial({color:b.arrow?0xb8a47d:0xff6a20}));m.position.fromArray(b.position);const v=new T.Vector3().fromArray(b.velocity);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.clone().normalize());m.visible=b.delay<=0;scene.add(m);bullets.push({...b,m,v})}selectedEnemy=wolf;sync()}
